Функция ПолучитьСуммарныйДолгКонтрагента(КонтрагентСсылка)

	СуммаДолга = 0;
	ВыборкаДоговоров = Справочник.Договоры.ВыбратьПоВладельцу(КонтрагентСсылка);

	Пока ВыборкаДоговоров.Следующий() Цикл
		Запрос = Новый Запрос;
		Запрос.Текст =
			"ВЫБРАТЬ
			|	ВзаиморасчетыОстатки.Сумма
			|ИЗ
			|	РегистрНакопления.Взаиморасчеты.Остатки(
			|		,
			|		ВзаиморасчетыОстатки.Договор = &Договор) КАК ВзаиморасчетыОстатки";

		Запрос.УстановитьПараметр("Договор", ВыборкаДоговоров.Ссылка);
		РезультатЗапроса = Запрос.Выполнить();
		ВыборкаОстатков = РезультатЗапроса.Выбрать();

		Пока ВыборкаОстатков.Следующий() Цикл
			Если ВыборкаОстатков.Сумма > 0 Тогда
				СуммаДолга = СуммаДолга + ВыборкаОстатков.Сумма;
			КонецЕсли;
		КонецЦикла;
	КонецЦикла;

	Возврат СуммаДолга;

КонецФункции
